"""Class for handling all Applications related to remote Monaco automation"""

from ..desktop.application_aut import Application_AUT
from interops.libraries.squish_actions.constants import MONACO_APP_NAME, MONACO_SCRIPTING_APP_NAME

class MonacoAutController(Application_AUT):

    def __init__(self, serverAddress: str, serverPort: int):
        Application_AUT.__init__(self, serverAddress, serverPort)

    @classmethod
    def monaco_aut(cls, serverAddress: str, serverPort: int, attachPort: int = 7501):
        """Function to modify variables in the default MonacoAutController class to target the main Monaco application,
        on a system with a squish server running.

        :param serverAddress: Host IP Address of the system you wish to target with a squish server running
        :type serverAddress: str
        :param serverPort: Network Port number the running squish server. Default value is 4322
        :type serverPort: int, optional
        :param attachPort: Network Port number to attach to running instance of Monaco (can be used for debugging purposes)
        :type attachPort: int, optional
        """
        aut_cls = cls(serverAddress, serverPort)
        aut_cls._aut_name = MONACO_APP_NAME
        aut_cls.attach_port = str(attachPort)
        return aut_cls

    @classmethod
    def monaco_script_aut(cls, serverAddress: str, serverPort: int, attachPort: int = 7502):
        """Function to modify variables in the default MonacoAutController class to target the Monaco Scripting (AdaptivePlanningWorkflow.exe)
        application used with the adpative planning workflow, on a system with a squish server running.

        :param serverAddress: Host IP Address of the system you wish to target with a squish server running
        :type serverAddress: str
        :param serverPort: Network Port number the running squish server. Default value is 4322
        :type serverPort: int, optional
        :param attachPort: Network Port number to attach to running instance of Monaco Script (can be used for debugging purposes)
        :type attachPort: int, optional
        """
        aut_cls = cls(serverAddress, serverPort)
        aut_cls._aut_name = MONACO_SCRIPTING_APP_NAME
        aut_cls.attach_port = str(attachPort)
        return aut_cls